171: 				// return 204 status for a patient whose allergy status is unknown
172: 				throw new NoContentFoundException();
173: 			} else if (allergies.getAllergyStatus().equals(Allergies.NO_KNOWN_ALLERGIES)) {
174: 				// empty list
175: 			} else if (allergies.getAllergyStatus().equals(Allergies.SEE_LIST)) {
176: 				// return list
177: 				allergiesList.addAll(allergies);
178: 			}
179: 		} else {
