206: 	 *      /patient/UUID/allergy/ALLERGYUUID means to delete one allergy from patient DELETE
207: 	 *      /patient/UUID/allergy/ means to delete all allergies from patient, back to Unknown
208: 	 *      Allergies state
209: 	 */
210: 	@Override
211: 	public void delete(String parentUniqueId, String uuid, String reason, RequestContext context) throws ResponseException {
212: 		if (parentUniqueId != null && uuid != null) {
213: 			// DELETE /patient/UUID/allergy/ALLERGYUUID means to delete one allergy from patient
214: 			Allergy allergy = getByUniqueId(uuid);
215: 			if (allergy == null) {
216: 				throw new ObjectNotFoundException();
217: 			}
218: 			Context.getPatientService().voidAllergy(allergy, reason);
219: 		} else if (parentUniqueId != null && uuid == null) {
220: 			// DELETE /patient/UUID/allergy/ means to delete all allergies from patient, back to Unknown Allergies state
221: 			Patient patient = Context.getPatientService().getPatientByUuid(parentUniqueId);
222: 			Allergies allergies = Context.getPatientService().getAllergies(patient);
223: 			for (Allergy allergy : allergies) {
224: 				Context.getPatientService().voidAllergy(allergy, reason);
225: 			}
226: 		}
227: 	}
